<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ChevronLeft, ChevronRight, PenLine, Save } from 'lucide-vue-next'
import { api, unwrap } from '@/api/client'
import type { Entry } from '@/types'
import EntryCard from '@/components/EntryCard.vue'

interface JournalData {date:string;journal:any;entries:Entry[]}
const today=new Date(),selected=ref(today.toISOString().slice(0,10)),data=ref<JournalData|null>(null),content=ref(''),editing=ref(false),fragment=ref(''),busy=ref(false)
const title=computed(()=>new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date(selected.value+'T12:00:00')))
const monthDays=computed(()=>{const d=new Date(selected.value+'T12:00:00'),y=d.getFullYear(),m=d.getMonth(),count=new Date(y,m+1,0).getDate();return Array.from({length:count},(_,i)=>`${y}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`)})
async function load(){const loaded=await unwrap<JournalData>(api.get(`/journals/${selected.value}`));data.value=loaded;content.value=loaded.journal.content||loaded.journal.generatedContent||'';editing.value=false}
function shiftMonth(n:number){const d=new Date(selected.value+'T12:00:00');d.setMonth(d.getMonth()+n,1);selected.value=d.toISOString().slice(0,10);load()}
async function save(){busy.value=true;try{await unwrap(api.put(`/journals/${selected.value}`,{content:content.value}));editing.value=false;load()}finally{busy.value=false}}
async function addFragment(){if(!fragment.value.trim())return;await unwrap(api.post('/entries',{type:'DIARY',content:fragment.value,occurredAt:new Date(selected.value+'T12:00:00').toISOString()}));fragment.value='';load()}
onMounted(load)
</script>

<template>
  <div class="page journal-page">
    <header class="page-header"><div><p class="eyebrow">DAILY PAGES</p><h1 class="page-title">日记</h1><p class="page-subtitle">原始片段一直保留，整理后的文字属于这一天。</p></div></header>
    <div class="journal-layout">
      <aside class="calendar card"><div class="calendar-head"><button class="icon-btn" @click="shiftMonth(-1)"><ChevronLeft :size="17"/></button><strong>{{new Date(selected+'T12:00:00').toLocaleDateString('zh-CN',{year:'numeric',month:'long'})}}</strong><button class="icon-btn" @click="shiftMonth(1)"><ChevronRight :size="17"/></button></div><div class="week"><span v-for="w in '一二三四五六日'" :key="w">{{w}}</span></div><div class="days"><span v-for="n in (new Date(monthDays[0]+'T12:00:00').getDay()+6)%7" :key="'x'+n"/><button v-for="day in monthDays" :key="day" :class="{active:day===selected,today:day===new Date().toISOString().slice(0,10)}" @click="selected=day;load()">{{Number(day.slice(-2))}}</button></div></aside>
      <main class="journal-content">
        <div class="journal-title"><div><p class="eyebrow">SELECTED DAY</p><h2>{{title}}</h2></div><button class="btn btn-secondary" @click="editing=!editing"><PenLine :size="15"/>{{editing?'查看':'整理'}}</button></div>
        <section class="written card"><div class="section-head"><h3 class="section-title">整理后的日记</h3></div><textarea v-if="editing" v-model="content" class="journal-editor" placeholder="把这一天整理成一篇日记……"/><div v-else-if="content" class="journal-text">{{content}}</div><div v-else class="empty">这一天还没有整理后的日记。</div><button v-if="editing" class="btn btn-primary save" :disabled="busy" @click="save"><Save :size="15"/>保存日记</button></section>
        <section class="section"><div class="section-head"><h3 class="section-title">原始片段</h3><span class="count">{{data?.entries.length||0}} 条</span></div><form class="fragment card" @submit.prevent="addFragment"><textarea v-model="fragment" placeholder="补记这一刻……"/><button class="btn btn-primary">记下</button></form><EntryCard v-for="e in data?.entries" :key="e.id" :entry="e" show-time/></section>
      </main>
    </div>
  </div>
</template>

<style scoped>
.journal-page{max-width:1280px}.journal-layout{display:grid;grid-template-columns:310px minmax(0,1fr);gap:42px;align-items:start}.calendar{position:sticky;top:28px;padding:22px 18px 20px;overflow:hidden;background:var(--primary);color:var(--primary-foreground);border-color:color-mix(in oklch,var(--primary-foreground) 12%,transparent);box-shadow:0 24px 60px color-mix(in oklch,var(--primary) 22%,transparent)}.calendar::after{content:"";position:absolute;width:160px;height:160px;right:-82px;bottom:-92px;border:30px solid color-mix(in oklch,var(--primary-foreground) 8%,transparent);border-radius:50%;pointer-events:none}.calendar-head{position:relative;z-index:1;display:flex;align-items:center;justify-content:space-between;font-size:11px}.calendar :deep(.icon-btn){color:var(--primary-foreground)}.calendar :deep(.icon-btn:hover){background:color-mix(in oklch,var(--primary-foreground) 12%,transparent);border-color:transparent}.week,.days{position:relative;z-index:1;display:grid;grid-template-columns:repeat(7,1fr);gap:5px}.week{margin:20px 0 8px;color:color-mix(in oklch,var(--primary-foreground) 55%,transparent);font-size:8px;font-weight:900;text-align:center}.days button{aspect-ratio:1;border:0;background:transparent;color:inherit;border-radius:calc(var(--radius)*.45);font-size:10px;transition:.16s}.days button:hover{background:color-mix(in oklch,var(--primary-foreground) 12%,transparent)}.days button.today{box-shadow:inset 0 0 0 1px color-mix(in oklch,var(--primary-foreground) 50%,transparent)}.days button.active{background:var(--primary-foreground);color:var(--primary);box-shadow:0 8px 20px color-mix(in oklch,var(--foreground) 22%,transparent)}.journal-title{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin:0 0 20px}.journal-title h2{font:650 31px/1.2 var(--font-display);letter-spacing:-.045em;margin:8px 0 0}.written{position:relative;min-height:330px;padding:30px 32px;overflow:hidden;background:repeating-linear-gradient(to bottom,color-mix(in oklch,var(--card) 94%,transparent) 0,color-mix(in oklch,var(--card) 94%,transparent) 35px,color-mix(in oklch,var(--border) 60%,transparent) 36px)}.written::before{content:"";position:absolute;left:18px;top:0;bottom:0;width:1px;background:color-mix(in oklch,var(--destructive) 18%,transparent)}.written .section-head{position:relative;z-index:1}.journal-text{position:relative;z-index:1;font-family:var(--font-display);white-space:pre-wrap;line-height:2.4;font-size:15px}.journal-editor{position:relative;z-index:1;width:100%;min-height:270px;border:0;background:transparent;outline:0;resize:vertical;font-family:var(--font-display);font-size:15px;line-height:2.4}.written :deep(.empty){background:color-mix(in oklch,var(--card) 70%,transparent)}.save{position:relative;z-index:1;margin-top:17px}.fragment{display:flex;gap:10px;padding:10px 10px 10px 18px;margin-bottom:13px;border-color:color-mix(in oklch,var(--diary-foreground) 16%,var(--border))}.fragment textarea{flex:1;min-height:46px;padding:10px 0;border:0;background:transparent;resize:none;outline:0;font-family:var(--font-display);line-height:1.7}.fragment .btn{align-self:flex-end}@media(max-width:960px){.journal-layout{grid-template-columns:270px minmax(0,1fr);gap:25px}}@media(max-width:760px){.journal-layout{grid-template-columns:1fr}.calendar{position:static}.journal-page{max-width:720px}.written{padding:24px 22px}.journal-title h2{font-size:25px}}
</style>
